CREATE TABLE `TrainingCourse` (`id` VARCHAR(191) NOT NULL,`title` VARCHAR(191) NOT NULL,`description` VARCHAR(191) NULL,`hours` INTEGER NOT NULL DEFAULT 1,`isActive` BOOLEAN NOT NULL DEFAULT true,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `TrainingEnrollment` (`id` VARCHAR(191) NOT NULL,`courseId` VARCHAR(191) NOT NULL,`employeeId` VARCHAR(191) NOT NULL,`status` VARCHAR(191) NOT NULL DEFAULT 'ASSIGNED',`assignedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`completedAt` DATETIME(3) NULL,`certificateUrl` VARCHAR(191) NULL,UNIQUE INDEX `TrainingEnrollment_courseId_employeeId_key`(`courseId`,`employeeId`),INDEX `TrainingEnrollment_employeeId_status_idx`(`employeeId`,`status`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ComplianceRecord` (`id` VARCHAR(191) NOT NULL,`title` VARCHAR(191) NOT NULL,`category` VARCHAR(191) NOT NULL,`status` VARCHAR(191) NOT NULL DEFAULT 'OPEN',`ownerId` VARCHAR(191) NULL,`dueDate` DATETIME(3) NULL,`evidenceUrl` VARCHAR(191) NULL,`notes` VARCHAR(191) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `ComplianceRecord_status_dueDate_idx`(`status`,`dueDate`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SystemAlert` (`id` VARCHAR(191) NOT NULL,`severity` VARCHAR(191) NOT NULL,`type` VARCHAR(191) NOT NULL,`title` VARCHAR(191) NOT NULL,`message` VARCHAR(191) NOT NULL,`status` VARCHAR(191) NOT NULL DEFAULT 'OPEN',`sourceType` VARCHAR(191) NULL,`sourceId` VARCHAR(191) NULL,`resolvedById` VARCHAR(191) NULL,`resolvedAt` DATETIME(3) NULL,`resolution` VARCHAR(191) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `SystemAlert_status_severity_createdAt_idx`(`status`,`severity`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `TrainingEnrollment` ADD CONSTRAINT `TrainingEnrollment_courseId_fkey` FOREIGN KEY (`courseId`) REFERENCES `TrainingCourse`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
